import{_ as r,c as t,o as e,ag as i}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"小程序资源","description":"nPlyr 的小程序与规则源来自哪里，以及如何添加你自己的源。","frontmatter":{"title":"小程序资源","description":"nPlyr 的小程序与规则源来自哪里，以及如何添加你自己的源。","layout":"doc"},"headers":[],"relativePath":"zh-CN/guide/miniapp-sources.md","filePath":"zh-CN/guide/miniapp-sources.md","lastUpdated":1791311600000}'),o={name:"zh-CN/guide/miniapp-sources.md"};function n(l,a,s,d,p,c){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="小程序资源" tabindex="-1">小程序资源 <a class="header-anchor" href="#小程序资源" aria-label="Permalink to &quot;小程序资源&quot;">​</a></h1><p>本页属于<strong>小程序</strong>指南章节——即 nPlyr 可以导入的社区小程序与规则源目录。nPlyr <strong>不</strong>随附固定的视频源列表；相反，源由你自行提供，应用内的管理器负责导入。</p><h2 id="资源来自哪里" tabindex="-1">资源来自哪里 <a class="header-anchor" href="#资源来自哪里" aria-label="Permalink to &quot;资源来自哪里&quot;">​</a></h2><ul><li><strong>hikerView 生态。</strong> nPlyr 与 Android 应用所用的同一批分享文本和 JSON 兼容，因此现有社区规则可直接导入。</li><li><strong>云分享。</strong> nPlyr 支持云后端 <strong>TextDB</strong>（云2）、<code>cmd.im</code>（302 重定向，云5）与 <strong>pasteme</strong>（云6），因此托管在那里的规则可以一步订阅。</li><li><strong>你自己的。</strong> 编写或改编一条规则并导入——请先参阅<a href="/zh-CN/guide/miniapps.html">小程序概览</a>与<a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>边界。</li></ul><h2 id="添加资源" tabindex="-1">添加资源 <a class="header-anchor" href="#添加资源" aria-label="Permalink to &quot;添加资源&quot;">​</a></h2><ol><li>在 nPlyr 中打开<strong>小程序</strong>（macOS 上是管理器窗口，iOS 上是一个页面）。</li><li>选择<strong>添加</strong>，粘贴分享文本 / JSON，或选择一个云源进行订阅。</li><li>该程序会出现在首页顶行——拖拽以重排。</li></ol><p>免费层级限制你一次可保留的导入程序数量；一次性解锁会移除该限制。</p><h2 id="兼容性是关键" tabindex="-1">兼容性是关键 <a class="header-anchor" href="#兼容性是关键" aria-label="Permalink to &quot;兼容性是关键&quot;">​</a></h2><p>并非每一条 Android 规则都在 nPlyr 上完全一致地运行。nPlyr 的引擎是 <strong>JavaScriptCore</strong>，而非 Java/Rhino，并且只模拟了经过筛选的 Java API 子集。在依赖某个源之前，请查阅<a href="/zh-CN/guide/miniapp-compatibility.html">兼容性</a>页面，并报告任何失败的规则（附上规则名称及其失败的步骤）。</p><blockquote><p>你在此浏览的目录由社区维护。nPlyr 并非第三方小程序的作者，也不为其内容背书——只安装你信任的源。</p></blockquote>',10)])])}const g=r(o,[["render",n]]);export{m as __pageData,g as default};
